--
-- Table structure for table `items`
--

DROP TABLE IF EXISTS `items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `item_category_id` bigint unsigned NOT NULL,
  `tax_id` bigint unsigned DEFAULT NULL,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `barcode` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `caution` longtext COLLATE utf8mb4_unicode_ci,
  `description` longtext COLLATE utf8mb4_unicode_ci,
  `price` decimal(19,6) NOT NULL DEFAULT '0.000000',
  `status` tinyint NOT NULL DEFAULT '5' COMMENT '5=Actif, 10=Inactif',
  `channels` json DEFAULT NULL,
  `allergen_flags` json DEFAULT NULL,
  `kiosk_emoji` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kds_station` enum('bar','cuisine_chaude','cuisine_froide','none') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `item_type` tinyint NOT NULL DEFAULT '5',
  `order` bigint NOT NULL DEFAULT '1',
  `is_featured` tinyint NOT NULL DEFAULT '5',
  `is_upsell` tinyint(1) NOT NULL DEFAULT '0',
  `is_chef_pick` tinyint(1) NOT NULL DEFAULT '0',
  `is_new` tinyint(1) NOT NULL DEFAULT '0',
  `is_available` tinyint(1) NOT NULL DEFAULT '1',
  `is_spicy` tinyint(1) NOT NULL DEFAULT '0',
  `is_vegetarian` tinyint(1) NOT NULL DEFAULT '0',
  `is_pork_free` tinyint(1) NOT NULL DEFAULT '0',
  `is_halal` tinyint(1) NOT NULL DEFAULT '0',
  `is_gluten_free` tinyint(1) NOT NULL DEFAULT '0',
  `chef_pick_order` int unsigned DEFAULT NULL,
  `creator_type` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `creator_id` bigint DEFAULT NULL,
  `editor_type` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `editor_id` bigint DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `items_item_category_id_foreign` (`item_category_id`),
  KEY `items_tax_id_foreign` (`tax_id`),
  KEY `idx_items_status_category` (`status`,`item_category_id`),
  KEY `idx_items_id_price` (`id`,`price`),
  KEY `items_upsell_status_index` (`is_upsell`,`status`),
  KEY `items_is_chef_pick_idx` (`is_chef_pick`),
  KEY `items_kiosk_filters_idx` (`is_available`,`is_halal`,`is_vegetarian`),
  KEY `items_barcode_idx` (`barcode`),
  KEY `items_kds_station_index` (`kds_station`),
  CONSTRAINT `items_item_category_id_foreign` FOREIGN KEY (`item_category_id`) REFERENCES `item_categories` (`id`),
  CONSTRAINT `items_tax_id_foreign` FOREIGN KEY (`tax_id`) REFERENCES `taxes` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=500 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

