  `branch_id` bigint unsigned NOT NULL,
  `actor_id` bigint unsigned DEFAULT NULL,
  `customer_id` bigint unsigned DEFAULT NULL,
  `surface` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL,
  `intent_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `hmac_signature` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `canonical_payload` json NOT NULL,
  `subtotal` decimal(19,6) NOT NULL DEFAULT '0.000000',
  `discount` decimal(19,6) NOT NULL DEFAULT '0.000000',
  `total_tax` decimal(19,6) NOT NULL DEFAULT '0.000000',
  `delivery_charge` decimal(19,6) NOT NULL DEFAULT '0.000000',
  `total_ttc` decimal(19,6) NOT NULL DEFAULT '0.000000',
  `currency` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'EUR',
  `expires_at` timestamp NOT NULL,
  `consumed_at` timestamp NULL DEFAULT NULL,
  `consumed_by_user_id` bigint unsigned DEFAULT NULL,
  `consumed_order_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_quotes_quote_token_unique` (`quote_token`),
  KEY `order_quotes_actor_id_foreign` (`actor_id`),
  KEY `order_quotes_customer_id_foreign` (`customer_id`),
  KEY `order_quotes_consumed_by_user_id_foreign` (`consumed_by_user_id`),
  KEY `order_quotes_consumed_order_id_foreign` (`consumed_order_id`),
  KEY `order_quotes_branch_surface_intent_idx` (`branch_id`,`surface`,`actor_id`,`intent_hash`,`expires_at`),
  KEY `order_quotes_branch_expires_idx` (`branch_id`,`expires_at`),
  CONSTRAINT `order_quotes_actor_id_foreign` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `order_quotes_branch_id_foreign` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE CASCADE,
  CONSTRAINT `order_quotes_consumed_by_user_id_foreign` FOREIGN KEY (`consumed_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `order_quotes_consumed_order_id_foreign` FOREIGN KEY (`consumed_order_id`) REFERENCES `orders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `order_quotes_customer_id_foreign` FOREIGN KEY (`customer_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1484 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
