--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `parent_order_id` bigint unsigned DEFAULT NULL,
  `order_serial_no` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `idempotency_key` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `loyalty_points_awarded` int DEFAULT NULL,
  `loyalty_customer_code` varchar(25) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_surface` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'kiosk | pos | web | mobile',
  `queue_number` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `business_date` date DEFAULT NULL,
  `token` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_id` bigint unsigned NOT NULL,
  `branch_id` bigint unsigned NOT NULL,
  `subtotal` decimal(19,6) NOT NULL,
  `discount` decimal(19,6) DEFAULT '0.000000',
  `delivery_charge` decimal(19,6) DEFAULT '0.000000',
  `total_tax` decimal(19,6) DEFAULT NULL,
  `total` decimal(19,6) NOT NULL,
  `fiscal_sequence_no` bigint unsigned DEFAULT NULL,
  `fiscal_alloc_error_at` timestamp NULL DEFAULT NULL,
  `order_type` tinyint NOT NULL DEFAULT '5',
  `order_datetime` timestamp NOT NULL DEFAULT '2026-05-05 02:05:25',
  `delivery_time` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `preparation_time` int NOT NULL DEFAULT '0',
  `is_advance_order` tinyint NOT NULL DEFAULT '5',
  `payment_method` bigint NOT NULL DEFAULT '1',
  `pos_payment_method` tinyint DEFAULT NULL,
  `pos_received_amount` decimal(19,6) DEFAULT '0.000000',
  `pos_payment_note` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payment_status` tinyint NOT NULL DEFAULT '10',
  `transaction_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `card_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` tinyint NOT NULL,
  `dining_table_id` bigint unsigned DEFAULT NULL,
  `delivery_boy_id` bigint DEFAULT NULL,
  `reason` text COLLATE utf8mb4_unicode_ci,
  `source` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `creator_type` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `creator_id` bigint DEFAULT NULL,
  `editor_type` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `editor_id` bigint DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `receipt_print_count` int unsigned NOT NULL DEFAULT '0' COMMENT 'NF525 W8.C-P3: count of receipt prints; 0=original, 1+=duplicata',
  PRIMARY KEY (`id`),
  UNIQUE KEY `orders_branch_id_idempotency_key_unique` (`branch_id`,`idempotency_key`),
  UNIQUE KEY `orders_branch_fiscal_seq_unique` (`branch_id`,`fiscal_sequence_no`),
  UNIQUE KEY `orders_branch_business_date_queue_unique` (`branch_id`,`business_date`,`queue_number`),
  KEY `idx_orders_branch_status` (`branch_id`,`status`),
  KEY `idx_orders_user_id` (`user_id`),
  KEY `idx_orders_datetime` (`order_datetime`),
  KEY `idx_orders_status` (`status`),
  KEY `orders_parent_order_id_index` (`parent_order_id`),
  CONSTRAINT `orders_branch_id_foreign` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`),
  CONSTRAINT `orders_parent_order_id_foreign` FOREIGN KEY (`parent_order_id`) REFERENCES `orders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `orders_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1492 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

